import sys
import logging
import platform
import subprocess
from inspect import ismethod
from functools import wraps


def choose_selector_way(func):
    def choose_way_select_element(self, selector, by="css"):
        select_element_script = None
        if by == "css":
            select_element_script = "document.querySelector(\'{}\')".format(selector)
        elif by == 'id':
            select_element_script = "document.getElementById(\'{}\')".format(selector)
        return func(self, select_element_script, by)

    return choose_way_select_element


def deprecated(cls):
    class DeprecatedCls(object):
        DEPRECATION_MESSAGE = "{} is deprecated, pls use taf.selenium.sbts_fsm3 for substitute"

        def __init__(self, *args, **kwargs):
            self.oInstance = cls(*args, **kwargs)

        def __getattribute__(self, name):
            try:
                attr = super(DeprecatedCls, self).__getattribute__(name)
            except AttributeError:
                pass
            else:
                return attr
            attr = self.oInstance.__getattribute__(name)
            if ismethod(attr):
                logging.warning(self.DEPRECATION_MESSAGE.format(attr.__name__))
                return attr

    return DeprecatedCls


def run_system_cmd_on_linux(command):
    if 'Linux' in platform.platform():
        try:
            ret = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            ret.wait()
            for line in ret.stdout.readlines():
                logging.info(line.strip())
        except Exception as e:
            logging.info("run_system_cmd_on_linux raise error: ", e)


def check_if_selenium_required_process_exist():
    run_system_cmd_on_linux('ps -ef | grep Xvfb')
    run_system_cmd_on_linux('ps -ef | grep geckodriver')
    run_system_cmd_on_linux('ps -ef | grep firefox')


def wait_for_operation_success(retry_times, exception=None, raised=True, log=False):  # noqa: C901
    """
    Raise particular type of exception after several times.
    Note: this decoration can only be used for a method in class.

    :param retry_times: how many times will be retried until wrapper func pass
    :type: retry_times: int
    :param exception: one kind of exception which will be raised or not
    :type exception: Exception
    :param raised: if raise exception or not
    :type raised: bool
    :param log: if need to print log or not, default False
    type log: bool
    """

    def decorator(func):
        def wrapper(self, *args, **kwargs):
            exc_value = None
            e = exception or Exception
            for _ in range(retry_times):
                try:
                    return func(self, *args, **kwargs)
                except e:
                    _, exc_value, _ = sys.exc_info()
            if log:
                logging.debug(exc_value)
            if raised:
                raise exc_value

        return wrapper

    return decorator


DEPRECATION_MESSAGE = (
    "The function {keyword_name} is deprecated and will no longer be maintained. "
    "Consider avoiding its use or contact support if enhancements are required."
)


def mark_deprecated(func):
    """This is a decorator which can be used to mark functions as deprecated.
    It will result in a warning being logged when the function is used."""

    @wraps(func)
    def wrapper(*args, **kwargs):
        logging.warning(DEPRECATION_MESSAGE.format(keyword_name=func.__name__))
        return func(*args, **kwargs)

    return wrapper











